arcelles</h3><p>Associations aux campagnes, surfaces exploitées, variétés et objectifs de rendement.</p></div><button class="panel-action" type="button" data-workspace-modal-open="planModal"><i class="bi bi-plus-lg"></i> Planifier une parcelle</button></div><div class="table-responsive"><table data-search-placeholder="Rechercher une campagne, une parcelle ou une variété"><thead><tr><th>Campagne</th><th>Parcelle</th><th>Variété</th><th>Surface planifiée</th><th>Surface exploitée</th><th>Objectif t/ha</th><th>Statut</th></tr></thead><tbody><?php foreach($campaignPlots as$x):?><tr><td><strong><?=e($x['campaign_code'])?></strong></td><td><?=e($x['plot_code'])?><small class="table-subline"><?=e($x['plot_name'])?></small></td><td><?=e($x['variety_name'])?></td><td><?=e(number_format($x['planned_area_ha'],3,',',' '))?> ha</td><td><?=e(number_format($x['actual_area_ha'],3,',',' '))?> ha</td><td><?=e(number_format($x['target_tons_per_ha'],3,',',' '))?></td><td><span class="status-badge status-<?=e($x['status'])?>"><?=e($x['status'])?></span></td></tr><?php endforeach;?><?php if(!$campaignPlots):?><tr><td colspan="7">Aucune parcelle planifiée.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?>

