itHarvest['version']=Agriculture::harvestVersion($h);?><button type="button" class="btn-table-action" data-workspace-modal-open="harvestModal" data-harvest-edit="<?=e(json_encode($editHarvest,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))?>" data-harvest-update-url="<?=e(base_url('agriculture/harvests/'.$h['id'].'/update'))?>"><i class="bi bi-pencil-square" aria-hidden="true"></i> Modifier</button><?php endif;?><?php if($h['status']==='submitted'):?><form method="post" action="<?=e(base_url('agriculture/harvests/'.$h['id'].'/validate'))?>" data-confirm-title="Valider la récolte" data-confirm="Cette validation créera l’entrée de stock agricole."><?=csrf_field()?><input type="hidden" name="_return_to" value="agriculture/harvests"><button class="btn-table-action"><i class="bi bi-check2"></i> Valider</button></form><?php else:?><span class="table-muted">—</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$harvests):?><tr><td colspan="10">Aucune récolte enregistrée.</td></tr><?php endif;?></tbody></table></div></section>

