_return_to" value="agriculture/transports"><button class="btn-table-action"><i class="bi bi-lock"></i> Valider / réserver</button></form><?php elseif($t['status']==='approved'):?><form method="post" action="<?=e(base_url('agriculture/transports/'.$t['id'].'/dispatch'))?>" data-confirm-title="Expédier le transport" data-confirm="Cette expédition diminuera le stock physique et placera la quantité en transit."><?=csrf_field()?><input type="hidden" name="_return_to" value="agriculture/transports"><button class="btn-table-action"><i class="bi bi-truck"></i> Expédier</button></form><?php else:?><span class="transport-next-step"><?=e(['in_transit'=>'Réception au pont-bascule','received'=>'Transport terminé','cancelled'=>'Bon annulé'][$t['status']]??'—')?></span><?php endif;?></td></tr><?php endforeach;?><?php if(!$transports):?><tr><td colspan="6"><div class="transport-empty"><i class="bi bi-truck" aria-hidden="true"></i><strong>Votre première expédition commence ici</strong><p>Créez un bon à partir d’un stock agricole validé et disponible.</p><button type="button" class="btn-secondary" data-workspace-modal-open="transportModal">Créer un bon de transport</button></div></td></tr><?php endif;?></tbody></table></div></section>

