<?php $transportDestination = $refs['transport_destination']['name'] ?? ''; $transportOrigin = ''; agro_modal_start('transportModal','bi-truck','Créer un bon de transport','Transport interne d’un stock agricole validé vers le site de réception SILO.','agriculture/transports');?><aside class="plot-context-card field-wide transport-modal-context"><div class="plot-context-title"><span><i class="bi bi-arrow-left-right"></i></span><div><small>FLUX INTERNE</small><strong>Ferme → <?=e($transportDestination ?: 'Site SILO indisponible')?></strong><p>Le site source est déterminé et contrôlé depuis le stock sélectionné.</p></div></div></aside><div class="transport-form-heading field-wide"><span>01</span><strong>Chargement</strong><small>Stock et quantité à acheminer</small></div><label class="field-wide"><span>Stock agricole disponible *</span><select name="stock_id" data-farm-transport-stock required><?php foreach($harvests as$h):if(empty($h['stock_id'])||!empty($h['has_draft_transport'])||!in_array($h['stock_status'],['available','reserved'],true))continue;$available=(float)$h['physical_quantity_kg']-(float)$h['reserved_quantity_kg'];if($available<=0)continue;if($transportOrigin==='')$transportOrigin=$h['site_name'];?><option value="<?=e($h['stock_id'])?>" data-route-origin="<?=e($h['site_name'])?>"><?=e($h['site_code'].' · '.$h['harvest_number'].' · '.$h['variety_name'].' — '.number_format($available,3,',',' ')).' kg disponibles'?></option><?php endforeach;if($transportOrigin===''):?><option value="">Aucun stock disponible sans BT en brouillon</option><?php endif;?></select><small>Seuls les stocks validés, disponibles, accessibles et sans BT en brouillon sont proposés. Le solde non réservé peut faire l’objet d’un nouveau transport.</small></label><label><span>Quantité à transporter (kg) *</span><input type="number" min="0.001" step="0.001" name="quantity_kg" required></label><div class="transport-form-heading field-wide"><span>02</span><strong>Transporteur</strong><small>Camion et personne responsable</small></div><label><span>Plaque du camion *</span><input name="truck_plate" data-uppercase required></label><label><span>Chauffeur *</span><input name="driver_name" required></label><div class="transport-form-heading field-wide"><span>03</span><strong>Itinéraire</strong><small>Trajet calculé depuis vos sites</small></div><label class="field-wide"><span>Trajet automatique</span><input name="route_description" data-farm-transport-route data-route-destination="<?=e($transportDestination)?>" value="<?=e($transportOrigin && $transportDestination ? $transportOrigin.' → '.$transportDestination : '')?>" readonly placeholder="Sélectionnez un stock ; un site SILO actif est nécessaire."><small>Déterminé automatiquement depuis la ferme du stock et le site de réception.</small></label><label class="field-wide"><span>Précisions sur le trajet (facultatif)</span><input name="route_notes" maxlength="200" placeholder="Ex. via Kasumbalesa, accès par la porte nord"><small>Le trajet complet, précisions comprises, est limité à 255 caractères.</small></label><?php agro_modal_end('Créer le BT en brouillon');?></div>
